import numpy as np
def voi(prior, likelihoods):
    # prior: (K,) 假设概率; likelihoods: (E,K,W) 每个实验在每种假设下观测的分布
    H = lambda p: -np.sum(p[p>0]*np.log(p[p>0]))
    out = []
    for lik in likelihoods:          # lik: (K,W)
        Hpost = 0.0
        for w in range(lik.shape[1]):
            joint = prior * lik[:, w]
            post = joint / joint.sum()
            Hpost += joint.sum() * H(post)
        out.append(H(prior) - Hpost)
    return np.array(out)
